import numpy as np
f=open('answer.xyz'); n=int(next(f));next(f);d=[l.split() for l in f];e=[x[0] for x in d];X=np.array([[float(v) for v in x[1:]] for x in d]);
ru=X[70]; p=X[47]; axis=ru-p;axis/=np.linalg.norm(axis)
def spin(points,center,axis,ang):
 # Rodrigues for row coords
 a=axis; K=np.array([[0,-a[2],a[1]],[a[2],0,-a[0]],[-a[1],a[0],0]])
 R=np.eye(3)*np.cos(ang)+(1-np.cos(ang))*np.outer(a,a)+np.sin(ang)*K
 return (points-center)@R.T+center
parts=[(range(0,19),range(19,43),'nap-ar'),(range(0,19),range(43,69),'nap-P'),(range(19,43),range(43,69),'ar-P')]
best=[]
for adeg in range(0,180,15):
 az=np.deg2rad(adeg); Rz=np.array([[np.cos(az),-np.sin(az),0],[np.sin(az),np.cos(az),0],[0,0,1]])
 for pdeg in range(0,360,15):
  Y=X.copy(); Y[19:43]=Y[19:43]@Rz.T; Y[43:69]=spin(Y[43:69],Y[47],axis,np.deg2rad(pdeg))
  mins=[]
  for aa,bb,name in parts:
   ds=[]
   for i in aa:
    for j in bb:
     d0=np.linalg.norm(Y[i]-Y[j]);
     # score heavy distances, atompair-specific minimum needed
     ds.append((d0,i,j,e[i],e[j]))
   mins.append(min(ds))
  # score, severe pair counts threshold depending atom types
  violations=0; margin=9
  for aa,bb,name in parts:
   for i in aa:
    for j in bb:
     d0=np.linalg.norm(Y[i]-Y[j])
     cutoff=2.0 if e[i]!='H' and e[j]!='H' else 1.65
     violations+=max(0,cutoff-d0)**2
     margin=min(margin,d0-cutoff)
