# optimize orientation using threshold set easier; report best
import numpy as np
from scipy.optimize import differential_evolution
f=open('answer.xyz'); n=int(next(f));next(f);d=[l.split() for l in f];e=[x[0] for x in d];X=np.array([[float(v) for v in x[1:]] for x in d]);ru=X[70];N=X[9];P=X[47]
def Raxis(axis,ang):
 a=axis/np.linalg.norm(axis);K=np.array([[0,-a[2],a[1]],[a[2],0,-a[0]],[-a[1],a[0],0]])
 return np.eye(3)*np.cos(ang)+(1-np.cos(ang))*np.outer(a,a)+np.sin(ang)*K
an=ru-N;an/=np.linalg.norm(an);ap=ru-P;ap/=np.linalg.norm(ap)
pairs=[]
for aa,bb in [(range(0,19),range(19,43)),(range(0,19),range(43,69)),(range(19,43),range(43,69))]:
 for i in aa:
  for j in bb:
   cut=2.1 if e[i]!='H' and e[j]!='H' else (1.85 if (e[i]=='H')^(e[j]=='H') else 1.7)
   pairs.append((i,j,cut))
def make(v):
 rn=Raxis(an,v[0]); rp=Raxis(ap,v[2]); c,s=np.cos(v[1]),np.sin(v[1]); rz=np.array([[c,-s,0],[s,c,0],[0,0,1]])
 Y=X.copy(); Y[:19]=(Y[:19]-N)@rn.T+N; Y[19:43]=Y[19:43]@rz.T; Y[43:69]=(Y[43:69]-P)@rp.T+P; return Y
def fun(v):
 Y=make(v); return sum(max(0,c-np.linalg.norm(Y[i]-Y[j]))**2 for i,j,c in pairs)
best=None
for seed in range(5):
 r=differential_evolution(fun,[(0,2*np.pi)]*3,tol=.0005,popsize=18,maxiter=800,polish=True,seed=seed)
 print(seed,r.fun,np.rad2deg(r.x))
 if best is None or r.fun<best.fun: best=r
Y=make(best.x)
for aa,bb,name in [(range(0,19),range(19,43),'nap-ar'),(range(0,19),range(43,69),'nap-P'),(range(19,43),range(43,69),'ar-P')]:
 vals=[]
 for i in aa:
  for j in bb: vals.append((np.linalg.norm(Y[i]-Y[j]),i,j,e[i],e[j]))
 print(name,sorted(vals)[:5])
with open('answer.xyz','w') as f:
 f.write(f'{n}\nRu(II) eta6-p-cymene N,P,Cl complex; 2-methyl-1,8-naphthyridine\n')
 for s,p in zip(e,Y): f.write(f'{s:<2s} {p[0]: .8f} {p[1]: .8f} {p[2]: .8f}\n')
